import{z as i,x as l,o as e,c as d,q as n,j as t,D as B,d as A,s as o,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"欧债危机","description":"","frontmatter":{"title":"欧债危机","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/eurozone-debt-crisis.md","filePath":"econ/eurozone-debt-crisis.md","lastUpdated":1791063341000}'),p={name:"econ/eurozone-debt-crisis.md"};function D(C,E,u,m,h,T){const r=l("Mermaid");return e(),d("div",null,[E[2]||(E[2]=n('<h1 id="欧债危机" tabindex="-1">欧债危机 <a class="header-anchor" href="#欧债危机" aria-label="Permalink to &quot;欧债危机&quot;">​</a></h1><div class="epigraph"><p>货币同盟拿走汇率与本国最后贷款人，主权债可以有多重均衡：利差升则路径不可持续。银行持有本国债，把主权挤兑写成银行资本空洞，再写回紧缩。</p><footer>—— De Grauwe 欧元区脆弱性；Lane 欧元区危机综述；Shambaugh；对照主干课欧元区危机与 OMT；Eichengreen</footer></div><p><a href="/econ/gfc-shadow-banking">上一课</a>的挤兑对象是私人批发债。本课缺口是 2010–12：挤兑对象换成同盟内主权债。主干<a href="/econ/eurozone-crisis">欧元区危机</a>已写无独立 \\(E\\)、无独立 \\(M\\)、无共同财政。经济史对照课把它放进序列：金本位是金属枷锁，东亚是原罪，2008 是影子链，欧债是<strong>共享货币但不共享主权预算</strong>。希腊有财政第一代味道，西班牙、爱尔兰是私人杠杆经银行变成主权——不要写成「南欧懒惰」。后课用央行独立性收束整条史。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>成员国发欧元债，收入也是欧元，却不能印欧元。De Grauwe：这使发达经济体的主权行为像新兴市场，可能失去市场准入。多重均衡：高利率验证不可持续。银行持有本国主权，利差升摧毁资本，信用紧缩摧毁财政，回路锁死。缺口不是再列 OCA 清单，而是：<strong>2008 的银行资本空洞在同盟里变成主权利差，因为缺一个对主权的明确最后买家。</strong> OMT 与「whatever it takes」把这一支补上，利差压缩——这是机制证据，不是名人名言。</p><p>TARGET2 余额是支付系统里的官方替代流，症状兼缓冲，不是原因本身。</p><h3 id="欧债不是「南欧懒」" tabindex="-1">欧债不是「南欧懒」 <a class="header-anchor" href="#欧债不是「南欧懒」" aria-label="Permalink to &quot;欧债不是「南欧懒」&quot;">​</a></h3><p>单位劳动成本与财政纪律的差异是事前漏洞，解释不了利差在几周内的非线性跳升，也解释不了为何爱尔兰、西班牙在危机前财政数字并不像希腊。懒惰叙事会漏掉银行–主权回路与同盟设计。紧缩的乘数在利差高企时更差，主权课与乘数课已经给语言：巩固可能抬高 \\(b\\) 的分子分母比。</p><p><span class="marginnote">Lane 的综述把跨境资本流、银行杠杆与突然停止放在欧元区内部。这是第三代在货币同盟里的版本：错配不一定是外币，可以是「不能印的本币」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照四次危机。(1) 金本位：保平价必须紧缩。(2) 东亚：保钉住与救美元债不能兼得。(3) 2008：救影子链需要印中心货币。(4) 欧债：救主权需要一个能印欧元的机构明确承诺。政策实验是 OMT：承诺改变均衡选择，不一定要实际买完。财政联盟、银行联盟是把担保从国家挪到同盟，减少回路。希腊式财政漏洞与爱尔兰式银行漏洞可以共存于同一利差跳升，识别要分两层冲击，不能用一个道德残差吸收。</p>',11)),(e(),t(s,null,{default:B(()=>[o(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GFC%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E7%A7%81%E4%BA%BA%E6%89%B9%E5%8F%91%E6%8C%A4%E5%85%91%22%5D%20--%3E%20SOV%5B%22%E5%90%8C%E7%9B%9F%E5%86%85%E4%B8%BB%E6%9D%83%E6%8C%A4%E5%85%91%22%5D%0A%20%20SOV%20--%3E%20LOOP%5B%22%E9%93%B6%E8%A1%8C%E6%8C%81%E6%9C%89%E6%9C%AC%E5%9B%BD%E5%80%BA%22%5D%0A%20%20LOOP%20--%3E%20OMT%5B%22%E6%98%8E%E7%A1%AE%E7%9A%84%E4%B8%BB%E6%9D%83%E6%9C%80%E5%90%8E%E4%B9%B0%E5%AE%B6%22%5D%0A%20%20OMT%20--%3E%20CBI%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E5%A4%AE%E8%A1%8C%E7%8B%AC%E7%AB%8B%E4%B8%8E%E5%A7%94%E6%89%98%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：OMT 式承诺像商店门口贴出「本店永不缺货」的告示——多数时候一张告示就止住了抢购，货根本不必真搬出来。承诺购债改变的是预期与均衡选择，实际动用的金额反而很小。")],-1)),E[4]||(E[4]=a("p",null,"不要用债务/GDP 排序当危机预测：意大利 \\(b\\) 高但回路与市场深度不同。阈值课已经警告过。救助贷款若附加过急的名义紧缩，乘数在利差高企时把分母打穿，\\(b\\) 短期上升，市场读成承诺失败——乘数课与可持续课在同盟里叠在同一张表上。OMT 是切换均衡的句子，不是财政转移的替代，也不能替代银行联盟的硬约束。",-1)),E[5]||(E[5]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[6]||(E[6]=a("p",null,"机制是货币主权缺失下的多重均衡。金本位下黄金是硬约束；欧元下规则与政治是软约束，直到被市场测试。银行监管允许主权债零风险权重，把回路写进制度。与地方财政软约束对照：成员国预期「同盟会救」，事前杠杆；不救则均衡跳到坏的一侧。OMT 把救助写成有条件的货币承诺，边界立刻变成独立性问题——下一课。",-1)),E[7]||(E[7]=a("p",null,"2008 互换线救的是美元腿；OMT 救的是欧元主权腿。欧洲银行可以两条腿同时瘸，国际金融课已分开写。内部贬值（工资物价）是 OCA 留下的调整阀，速度慢于名义汇率，于是失业承担了本该由 \\(E\\) 承担的一截——这是同盟相对东亚钉住的额外刚性，不是文化。",-1)),E[8]||(E[8]=a("p",null,[a("span",{class:"marginnote"},"Shambaugh 把危机写成同盟内突然停止。突然停止文献从新兴市场迁到欧元区，关键迁移是「本币不能印」。")],-1)),(e(),t(s,null,{default:B(()=>[o(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E5%9B%9B%E6%AC%A1%E5%8D%B1%E6%9C%BA%3A%20%E5%90%84%E8%87%AA%E5%9C%A8%E4%BF%9D%E4%BB%80%E4%B9%88%E9%94%9A%3F%22%7D%0A%20%20GOLD%5B%22%E9%87%91%E6%9C%AC%E4%BD%8D%3A%20%E4%BF%9D%E9%BB%84%E9%87%91%E5%B9%B3%E4%BB%B7%22%5D%20--%3E%20C1%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E5%86%85%E9%83%A8%E9%80%9A%E7%BC%A9%E7%B4%A7%E7%BC%A9%22%5D%0A%20%20ASIA%5B%22%E4%B8%9C%E4%BA%9A%3A%20%E4%BF%9D%E9%92%89%E4%BD%8F%E6%B1%87%E7%8E%87%22%5D%20--%3E%20C2%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E8%80%97%E5%B0%BD%E5%82%A8%E5%A4%87%E4%B8%8E%E7%BE%8E%E5%85%83%E8%BF%9D%E7%BA%A6%22%5D%0A%20%20GFC08%5B%222008%3A%20%E4%BF%9D%E5%BD%B1%E5%AD%90%E6%89%B9%E5%8F%91%E9%93%BE%22%5D%20--%3E%20C3%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E9%A1%BB%E5%8D%B0%E4%B8%AD%E5%BF%83%E8%B4%A7%E5%B8%81%E6%95%91%E7%BE%8E%E5%85%83%E8%85%BF%22%5D%0A%20%20EZ%5B%22%E6%AC%A7%E5%80%BA%3A%20%E4%BF%9D%E5%85%B1%E5%90%8C%E8%B4%A7%E5%B8%81%22%5D%20--%3E%20C4%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E7%BC%BA%E4%B8%BB%E6%9D%83%E6%9C%80%E5%90%8E%E4%B9%B0%E5%AE%B6%2C%20%E5%88%A9%E5%B7%AE%E8%B7%B3%E5%8D%87%22%5D%0A%20%20C4%20--%3E%20OMT%5B%22OMT%20%E8%A1%A5%E4%B8%8A%E6%9C%80%E5%90%8E%E4%B9%B0%E5%AE%B6%3A%20%E5%88%87%E6%8D%A2%E5%9D%87%E8%A1%A1%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[9]||(E[9]=n('<p><span class="marginnote">术语翻译：「主权债零风险权重」是监管规则——银行持有本国国债不必预留资本金，账本上它被当成绝对安全。于是银行放心重仓本国债，主权一出事银行资本一起塌，回路被制度亲手写死。</span></p><p><span class="marginnote">数字实例：东南亚 1997 年名义汇率一次性贬 30%—50%，一步到位；希腊走内部贬值，靠多年工资下调才压缩不到两成单位劳动成本，失业率一度超过 27%。同样的实际调整量，汇率贬值一次付清，内部贬值按失业率分期、利息高昂。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写主干欧元区危机的全部 TARGET2 会计，不提供主权债交易步骤。救助条件的法律文本不是机制核。经济史倒数第二课到此：下一部把独立央行如何从这些危机里长出来，以及独立与最后贷款人如何互相限制。后课默认：欧债用同盟设计 × 银行回路 × 多重均衡读；禁止文化懒惰论当主因果。量化栏的主权 CDS 基差是价格症状，本课不搬定价公式，以免吞并微观结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共享货币、不共享财政，使主权可被挤兑。</li><li>银行持有本国债，把利差写成资本与紧缩回路。</li><li>OMT 类承诺切换均衡，是机制证据。</li><li>与金本位、东亚、2008 对照的是约束形态，不是道德。</li><li>内部贬值慢于名义汇率，失业承担了本该由 \\(E\\) 承担的调整。</li><li>出处：De Grauwe；Lane；Shambaugh；主干欧元区危机课。</li></ul>',6))])}const c=i(p,[["render",D]]);export{f as __pageData,c as default};
